mapper.sql:
( SELECT id, sku, product_name, source_platform, sync_time, create_date FROM ( SELECT l.id, l.sku, l.product_name, l.source_platform, l.sync_time, l.create_date, ROW_NUMBER() OVER (PARTITION BY l.sku ORDER BY l.sync_time DESC, l.id DESC) AS rn FROM t_gigab2b_product_list l INNER JOIN bx ON bx.sku = l.sku
( l.sku LIKE CONCAT('%', #{name}, '%') OR l.product_name LIKE CONCAT('%', #{name}, '%') )
) ranked WHERE ranked.rn = 1 )

( SELECT id, sku, product_name, sync_time, price, exclusive_price, discounted_price, currency, seller_available_inventory, buyer_available_inventory, sku_available, detail_json, price_json, inventory_json FROM ( SELECT s1.id, s1.sku, s1.product_name, s1.sync_time, s1.price, s1.exclusive_price, s1.discounted_price, s1.currency, s1.seller_available_inventory, s1.buyer_available_inventory, s1.sku_available, s1.detail_json, s1.price_json, s1.inventory_json, ROW_NUMBER() OVER ( PARTITION BY s1.sku ORDER BY (CASE WHEN IFNULL(s1.price,0) > 0 OR IFNULL(s1.discounted_price,0) > 0 OR IFNULL(s1.exclusive_price,0) > 0 THEN 2 WHEN s1.price_json IS NOT NULL AND s1.price_json NOT IN ('', '{}', 'null') THEN 1 ELSE 0 END) DESC, s1.sync_time DESC, s1.id DESC ) AS rn FROM t_gigab2b_product_snapshot s1 WHERE s1.detail_json IS NOT NULL AND s1.sku IN
#{sku}
) sx WHERE sx.rn = 1 )

mapper.select:
SELECT COUNT(1) FROM t_gigab2b_product_family_index p WHERE p.is_primary = 1 AND p.collected = 1
AND EXISTS ( SELECT 1 FROM t_gigab2b_product_family_index m WHERE m.family_sku = p.family_sku AND m.collected = 1 AND ( m.sku LIKE CONCAT('%', #{name}, '%') OR m.product_name LIKE CONCAT('%', #{name}, '%') OR m.variant_label LIKE CONCAT('%', #{name}, '%') OR m.item_code LIKE CONCAT('%', #{name}, '%') ) )
AND EXISTS ( SELECT 1 FROM t_gigab2b_product_family_index m WHERE m.family_sku = p.family_sku AND m.collected = 1 AND m.giga_category_id IN
#{cid}
)

SELECT p.list_id FROM t_gigab2b_product_family_index p WHERE p.is_primary = 1 AND p.collected = 1 AND p.list_id IS NOT NULL
AND EXISTS ( SELECT 1 FROM t_gigab2b_product_family_index m WHERE m.family_sku = p.family_sku AND m.collected = 1 AND ( m.sku LIKE CONCAT('%', #{name}, '%') OR m.product_name LIKE CONCAT('%', #{name}, '%') OR m.variant_label LIKE CONCAT('%', #{name}, '%') OR m.item_code LIKE CONCAT('%', #{name}, '%') ) )
AND EXISTS ( SELECT 1 FROM t_gigab2b_product_family_index m WHERE m.family_sku = p.family_sku AND m.collected = 1 AND m.giga_category_id IN
#{cid}
)
ORDER BY COALESCE(p.sync_time, p.create_date) DESC, p.sku DESC LIMIT #{offset}, #{limit}

SELECT
FROM t_gigab2b_product_list l INNER JOIN ( SELECT id, sku, product_name, sync_time, price, exclusive_price, discounted_price, currency, seller_available_inventory, buyer_available_inventory, sku_available, detail_json, price_json, inventory_json FROM ( SELECT s1.id, s1.sku, s1.product_name, s1.sync_time, s1.price, s1.exclusive_price, s1.discounted_price, s1.currency, s1.seller_available_inventory, s1.buyer_available_inventory, s1.sku_available, s1.detail_json, s1.price_json, s1.inventory_json, ROW_NUMBER() OVER ( PARTITION BY s1.sku ORDER BY (CASE WHEN IFNULL(s1.price,0) > 0 OR IFNULL(s1.discounted_price,0) > 0 OR IFNULL(s1.exclusive_price,0) > 0 THEN 2 WHEN s1.price_json IS NOT NULL AND s1.price_json NOT IN ('', '{}', 'null') THEN 1 ELSE 0 END) DESC, s1.sync_time DESC, s1.id DESC ) AS rn FROM t_gigab2b_product_snapshot s1 WHERE s1.sku IN ( SELECT DISTINCT l0.sku FROM t_gigab2b_product_list l0 WHERE l0.id IN
#{id}
) ) sx WHERE sx.rn = 1 ) s ON s.sku = l.sku WHERE l.id IN
#{id}

SELECT * FROM ( SELECT , ROW_NUMBER() OVER (PARTITION BY l.sku ORDER BY l.sync_time DESC, l.id DESC) AS rn FROM t_gigab2b_product_list l INNER JOIN ( SELECT id, sku, product_name, sync_time, price, exclusive_price, discounted_price, currency, seller_available_inventory, buyer_available_inventory, sku_available, detail_json, price_json, inventory_json FROM ( SELECT s1.id, s1.sku, s1.product_name, s1.sync_time, s1.price, s1.exclusive_price, s1.discounted_price, s1.currency, s1.seller_available_inventory, s1.buyer_available_inventory, s1.sku_available, s1.detail_json, s1.price_json, s1.inventory_json, ROW_NUMBER() OVER ( PARTITION BY s1.sku ORDER BY (CASE WHEN IFNULL(s1.price,0) > 0 OR IFNULL(s1.discounted_price,0) > 0 OR IFNULL(s1.exclusive_price,0) > 0 THEN 2 WHEN s1.price_json IS NOT NULL AND s1.price_json NOT IN ('', '{}', 'null') THEN 1 ELSE 0 END) DESC, s1.sync_time DESC, s1.id DESC ) AS rn FROM t_gigab2b_product_snapshot s1 WHERE s1.sku IN
#{sku}
) sx WHERE sx.rn = 1 ) s ON s.sku = l.sku WHERE l.sku IN
#{sku}
) t WHERE t.rn = 1

